fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 288);
        host::display::state_set(2, 0);
        host::display::state_set(3, 336);
    }
    let mut temp: i32 = host::display::state_get(1);
    let mut heater: i32 = host::display::state_get(2);
    let mut set: i32 = host::display::state_get(3);
    if host::display::pointer_down() == 1 {
        set = 192 + (h - host::display::pointer_y()) * 288 / h;
    }
    if temp < set - 16 { heater = 1; }
    if temp > set + 16 { heater = 0; }
    temp = temp + heater * 10;
    temp = temp - (temp - 80) / 96;
    host::display::state_set(1, temp);
    host::display::state_set(2, heater);
    host::display::state_set(3, set);
    host::display::clear(0x0c0c10);
    let tube_x: i32 = w / 2 - 20;
    let base: i32 = h - 60;
    host::display::fill_rect(tube_x - 4, 56, 48, base - 52, 0x1c1c24);
    let bar: i32 = temp * 5 / 8;
    host::display::fill_rect(tube_x, base - bar, 40, bar, if heater == 1 { 0xe05030 } else { 0xc04040 });
    let sp: i32 = base - set * 5 / 8;
    host::display::fill_rect(tube_x - 12, sp - 10, 64, 1, 0xd0d0d0);
    host::display::fill_rect(tube_x - 12, sp + 10, 64, 1, 0xd0d0d0);
    if heater == 1 {
        host::display::fill_rect(tube_x, base + 10, 40, 14, 0xff8020);
        host::display::draw_string(tube_x + 50, base + 12, "HEAT ON", 0xff8020, 1);
    }
    host::display::draw_string(30, 30, "TEMP", 0x808080, 2);
    host::display::draw_number(110, 30, temp / 16, 0xffffff, 2);
    host::display::draw_string(30, 60, "SET", 0x808080, 1);
    host::display::draw_number(80, 60, set / 16, 0xa0a0a0, 1);
    host::display::draw_string(30, h - 24, "DRAG UP DOWN = SETPOINT", 0x505050, 1);
    host::display::present();
}
